model.en:
Add timeouts, a readiness flag, a graceful shutdown, and a process net:

import { createServer } from 'node:http';
import { app } from './app.js';
import { logger } from './logger.js';
import { closePool } from './db.js';

let ready = false;
const server = createServer(app);
server.requestTimeout = 30_000;   // bound every request (unit 05)
server.headersTimeout = 10_000;

async function shutdown(code = 0) {
  ready = false;                   // readiness off → LB drains us
  server.close(async () => {       // stop accepting; finish in-flight
    await closePool();
    process.exit(code);
  });
  setTimeout(() => process.exit(code), 10_000).unref(); // hard cap
}

process.on('SIGTERM', () => shutdown(0));
process.on('uncaughtException', (err) => { logger.fatal({ err }); shutdown(1); });
process.on('unhandledRejection', (err) => { logger.fatal({ err }); shutdown(1); });

server.listen(3000, () => { ready = true; logger.info('up'); });
// expose readiness: GET /readyz returns 200 iff `ready`

Why it's right: timeouts stop a slow client from pinning a connection; flipping readiness BEFORE server.close lets the LB stop routing new work so a rollout drops zero requests; the hard-timeout is unref'd so it can't keep the loop alive; and the process net records then exits with code 1, leaving the restart to a supervisor instead of serving from a corrupted state.

model.ru:
Добавь таймауты, флаг readiness, graceful shutdown и сеть процесса:

import { createServer } from 'node:http';
import { app } from './app.js';
import { logger } from './logger.js';
import { closePool } from './db.js';

let ready = false;
const server = createServer(app);
server.requestTimeout = 30_000;   // ограничь каждый запрос (юнит 05)
server.headersTimeout = 10_000;

async function shutdown(code = 0) {
  ready = false;                   // readiness off → LB сливает нас
  server.close(async () => {       // прекрати приём; доделай в полёте
    await closePool();
    process.exit(code);
  });
  setTimeout(() => process.exit(code), 10_000).unref(); // жёсткий кэп
}

process.on('SIGTERM', () => shutdown(0));
process.on('uncaughtException', (err) => { logger.fatal({ err }); shutdown(1); });
process.on('unhandledRejection', (err) => { logger.fatal({ err }); shutdown(1); });

server.listen(3000, () => { ready = true; logger.info('up'); });
// отдай readiness: GET /readyz возвращает 200 iff `ready`

Почему верно: таймауты не дают медленному клиенту удержать соединение; переключение readiness ДО server.close даёт LB перестать слать новую работу, так что раскат теряет ноль запросов; жёсткий таймаут с unref не держит loop живым; а сеть процесса фиксирует и выходит с кодом 1, оставляя перезапуск супервизору вместо обслуживания из испорченного состояния.
